lab.testCode:
db = sqlite3.connect(':memory:')
try:
    db.execute('CREATE TABLE notes (id TEXT PRIMARY KEY, text TEXT, version INTEGER NOT NULL)')
    db.execute('INSERT INTO notes VALUES (?, ?, ?)', ('n1', 'draft', 1))
    db.commit()
    first = update_note(db, 'n1', 'first edit', '"v1"')
    assert first == {'status': 200, 'etag': '"v2"'}
    assert update_note(db, 'n1', 'stale edit', '"v1"') == {'status': 412}
    assert db.execute('SELECT text, version FROM notes WHERE id = ?', ('n1',)).fetchone() == ('first edit', 2)
    print('PASS: stale edit cannot overwrite')
    assert update_note(db, 'missing', 'anything', '"v1"') == {'status': 404}
    assert update_note(db, 'n1', 'reviewed edit', '"v2"') == {'status': 200, 'etag': '"v3"'}
    print('PASS: missing and refreshed tag')
finally:
    db.close()
